Method.Source:
    /// <summary>
    /// Write the record
    /// </summary>
    void write()
    {
        FormDataSource              metSalesLineExt_ds;
        METSalesLine                metSalesLine;
        SalesLIne                   metSalesLIneStd;

        next write();

        metSalesLineExt_ds = this.formRun().dataSource(formDataSourceStr(ReturnTable, metSalesLine));

        if (metSalesLineExt_ds)
        {
            metSalesLIneStd      = this.cursor();
            metSalesLine   = metSalesLineExt_ds.cursor();
            
            metSalesLIneStd.metPackMETSalesLine(metSalesLine);
  
            //insert in correct order Parent, then extension
            metSalesLine.SysExtensionSerializerExtensionMap::insertAfterBaseTable(metSalesLIneStd);
        }

    }
